pub type BankAccount = {
  balance: Float64;
}

fn BankAccount.deposit(self: &mut BankAccount, amount: Float64) -> Unit {
  self.balance = self.balance + amount;
}

fn BankAccount.withdraw(self: &mut BankAccount, amount: Float64) -> Bool {
  if self.balance >= amount {
    self.balance = self.balance - amount;
    return true;
  }
  return false;
}

fn BankAccount.transfer(self: &mut BankAccount, amount: Float64, other: &mut BankAccount) -> Bool {
  if self.withdraw(amount) {
    other.deposit(amount);
    return true;
  }
  return false;
}

fn main() -> Int {
  var a = BankAccount{ balance: 100.0 };
  var b = BankAccount{ balance: 50.0 };
  a.deposit(25.0);
  a.transfer(30.0, &mut b);
  return (a.balance + b.balance) as Int;
}
